(function () {
  'use strict';
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };

  /* ---------------- Release + install commands ---------------- */
  // site/release.js is generated by scripts/release.mjs from packages/unpolish/package.json
  // and release.config.json. Every command, download link and the agent prompt below is
  // derived from it, so switching to a public location or to npm is a config change only.
  var R = window.UNPOLISH_RELEASE || {};
  var name = R.name || 'unpolish';
  var version = R.version || '';
  var exe = R.executable || name;
  var published = R.published === true;
  var here = new URL('unpolish/', location.href);
  here.search = ''; here.hash = '';
  var files = R.distUrl ? new URL(R.distUrl) : here;
  var tarball = R.tarballUrl || new URL(R.tarball || (name + '-' + version + '.tgz'), files).href;
  var docs = R.docsUrl || new URL('README.md', files).href;
  var localOnly = !published && (function () {
    try {
      var u = new URL(tarball);
      return u.protocol === 'file:' || /^(localhost|127\.|0\.0\.0\.0|\[::1\])/.test(u.hostname);
    } catch (e) { return false; }
  })();
  var latestSpec = exe + '@latest';
  var pinnedSpec = exe + '@' + version;
  var runSpec = published ? latestSpec : tarball;
  var promptSpec = published ? pinnedSpec : tarball;
  var nodeNeed = (function (range) {
    if (!range) return 'Node.js';
    var m = /^>=\s*(\d+(?:\.\d+)*)$/.exec((range || '').trim());
    return m ? 'Node.js ' + m[1] + ' or later' : 'Node.js ' + range;
  })(R.node);

  function command(spec, sub) { return 'npx ' + spec + ' ' + (sub || 'init'); }
  var visibleCmd = command(runSpec, 'init');
  var npmInstall = 'npm install --save-exact ' + (published ? pinnedSpec : tarball);

  function prompt() {
    var source = published
      ? ['Package: ' + name + ' ' + version + ' on npm. Docs: ' + docs]
      : ['Unpolish ' + version + ' is not on the npm registry yet. Install it from this package file, and do not install "' + name + '" from the registry:',
         '  ' + tarball]
        .concat(localOnly ? ['  (This file is served from the computer that showed me the prompt; it only works on that machine.)'] : [])
        .concat(['Docs: ' + docs]);
    return [
      'Install Unpolish in this prototype.',
      '',
      'Unpolish adds reversible lo-fi review themes (Black & White, Sketch, Blueprint, Pastel Blocks) to a working web prototype. It must not change the app\'s logic, routes, state, markup or existing styles.'
    ].concat(source, [
      'The installer needs ' + nodeNeed + '. The installed result has no Node requirement.',
      '',
      '1. Inspect the project: package manager, framework, client entry or root layout, static folder, base path, and any existing Unpolish setup. In a monorepo, pick the app to review.',
      '2. Preview the installer\'s plan from the project folder; it changes nothing:',
      '   ' + command(promptSpec, 'init --dry-run'),
      '   (in a monorepo add --cwd <app folder>)',
      '3. If the plan fits, run ' + command(promptSpec, 'init') + '. It uses the project\'s package manager, pins the exact version and keeps any existing unpolish.config.json. Exit code 2 means it changed nothing and printed manual steps (also available with --json): apply them with the smallest change that follows the project\'s conventions. Don\'t touch unrelated files, formatting or dependencies.',
      '4. Review the diff. Keep "defaultTheme": "original" in unpolish.config.json. Add "exclude" selectors only for regions that must keep their look, such as logos, maps, charts or video.',
      '5. Verify: restart the dev server if it was running, open the app, press \\ and switch themes; check that navigation, forms and dialogs still work; open the page with ?unpolish=sketch&unpolish-ui=hidden; choose Original and confirm it looks exactly as before. Run the project\'s tests, linter and type check, and a production build.',
      '6. Deployed previews show Unpolish only after they are rebuilt and redeployed. It is included in every build by default so review links work there; only restrict it (--scope dev) if I ask.',
      '7. Report the files changed, what I need to restart, rebuild or redeploy, anything that may need a role hint or override, known limits (canvas/WebGL, cross-origin iframes and closed shadow roots are left as they are), and how to remove it: ' + command(promptSpec, 'remove') + ' (keeps unpolish.config.json; --purge deletes it).',
      ''
    ]).join('\n');
  }

  $('#prompt-text').textContent = prompt();
  $$('[data-cmd]').forEach(function (el) { el.textContent = visibleCmd; });
  $$('[data-cmd-remove]').forEach(function (el) { el.textContent = command(runSpec, 'remove'); });
  $$('[data-npm-install]').forEach(function (el) { el.textContent = npmInstall; });
  $$('[data-dist]').forEach(function (el) {
    var file = el.getAttribute('data-dist');
    var abs = { 'unpolish.js': R.bundleUrl, 'unpolish.config.json': R.configUrl, 'unpolish.config.schema.json': R.schemaUrl, 'README.md': R.docsUrl }[file];
    el.href = abs || new URL(file, files).href;
  });
  $$('[data-tarball]').forEach(function (el) { el.href = tarball; });
  $$('[data-node-note]').forEach(function (el) { el.textContent = 'The command needs ' + nodeNeed + '. The script tag under Manual installation doesn’t.'; });
  $$('[data-local-note]').forEach(function (el) { el.hidden = !localOnly; });
  if (R.version) $('#version').textContent = R.version;

  // Long commands scroll inside their box; fade the cut edge while there is more to see.
  function markOverflow() {
    $$('.cmd-text').forEach(function (el) {
      el.classList.toggle('overflows', el.scrollLeft + el.clientWidth < el.scrollWidth - 1);
    });
  }
  $$('.cmd-text').forEach(function (el) { el.addEventListener('scroll', markOverflow, { passive: true }); });
  addEventListener('resize', markOverflow);
  markOverflow();

  /* ---------------- Clipboard + feedback ---------------- */
  var CHECK = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  // Resolves true only when the text is really on the clipboard.
  function copy(text) {
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = text; ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none';
      document.body.appendChild(ta); ta.select();
      var ok = false;
      try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
      ta.remove();
      return ok;
    }
    if (navigator.clipboard && window.isSecureContext) return navigator.clipboard.writeText(text).then(function () { return true; }, fallback);
    return Promise.resolve(fallback());
  }
  var toastEl = $('#toast'), toastTimer;
  function toast(html) {
    toastEl.innerHTML = html;
    clearTimeout(toastTimer);
    toastEl.classList.add('show');
    toastTimer = setTimeout(function () { toastEl.classList.remove('show'); }, 2600);
  }
  function confirmCopy(btn, label) {
    var swap = btn.querySelector('.swap');
    if (!btn._orig) btn._orig = swap.innerHTML;
    swap.innerHTML = CHECK + '<span>' + label + '</span>';
    clearTimeout(btn._t);
    btn._t = setTimeout(function () { swap.innerHTML = btn._orig; btn._orig = null; }, 1800);
  }
  function selectText(el) {
    el.focus({ preventScroll: true });
    var range = document.createRange(); range.selectNodeContents(el);
    var sel = getSelection(); sel.removeAllRanges(); sel.addRange(range);
  }
  var MANUAL = '<span>Couldn’t copy automatically. The text is selected — press Ctrl+C or ⌘C.</span>';
  $$('[data-copy-cmd]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      copy(visibleCmd).then(function (ok) {
        if (ok) { confirmCopy(btn, 'Copied'); return; }
        selectText(btn.parentNode.querySelector('[data-cmd]'));
        toast(MANUAL);
      });
    });
  });
  $$('[data-copy-prompt]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      copy(prompt()).then(function (ok) {
        if (ok) { confirmCopy(btn, 'Prompt copied'); toast(CHECK + '<span>Paste it into your coding agent.</span>'); return; }
        var pre = $('#prompt-text');
        pre.closest('details').open = true;
        pre.scrollIntoView({ block: 'center' });
        selectText(pre);
        toast(MANUAL);
      });
    });
  });

  /* ---------------- Nav border on scroll ---------------- */
  var nav = $('.nav');
  var onScroll = function () { nav.classList.toggle('scrolled', window.scrollY > 8); };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  /* ---------------- Live harness in a frame ---------------- */
  function whenApi(frame, cb) {
    var tries = 0;
    function poll() {
      var w = frame.contentWindow;
      if (w && w.Unpolish && w.document.querySelector('unpolish-harness')) { cb(w.Unpolish); return; }
      if (++tries < 150) setTimeout(poll, 100);
    }
    frame.addEventListener('load', function () { tries = 0; poll(); });
    poll();
  }
  function radios(group, onPick) {
    group.addEventListener('click', function (e) {
      var b = e.target.closest('button[role="radio"]');
      if (b) onPick(b);
    });
    group.addEventListener('keydown', function (e) {
      var d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
      if (!d) return;
      e.preventDefault();
      var bs = $$('button[role="radio"]', group), i = bs.indexOf(document.activeElement);
      var n = bs[(i + d + bs.length) % bs.length];
      onPick(n); n.focus();
    });
  }
  function check(group, value) {
    $$('button[role="radio"]', group).forEach(function (b) {
      var on = (b.getAttribute('data-theme') || b.getAttribute('data-v')) === String(value);
      b.setAttribute('aria-checked', String(on));
      b.tabIndex = on ? 0 : -1;
    });
  }

  /* Hero demo */
  var seg = $('#demo-themes'), select = $('#demo-select'), demo = null;
  function syncDemo(state) { check(seg, state.theme); select.value = state.theme; }
  whenApi($('#demo-frame'), function (api) {
    if (demo === api) return;
    demo = api;
    api.on('change', syncDemo);
    syncDemo(api.state());
  });
  radios(seg, function (b) { if (demo) demo.setTheme(b.getAttribute('data-theme')); });
  select.addEventListener('change', function () { if (demo) demo.setTheme(select.value); });

  /* Configurator: a slice of the panel driving its own preview */
  var hints = { 'black-white': 'Status patterns and contrast', sketch: 'Stroke wobble and shading', blueprint: 'Drafting grid and corner marks', pastel: 'Color fields' };
  var cfg = null, details = $('#cfg-details'), detailsVal = $('#cfg-details-val');
  var groups = {};
  $$('[data-cfg]').forEach(function (g) { groups[g.getAttribute('data-cfg')] = g; });
  function syncCfg() {
    if (!cfg) return;
    var st = cfg.state();
    if (st.theme === 'original') { cfg.setTheme('sketch'); return; }
    var s = st.settings;
    check(groups.theme, st.theme);
    check(groups.images, s.images);
    check(groups.lines, s.border.style);
    check(groups.radius, s.radius);
    check(groups.typography, s.typography);
    if (document.activeElement !== details) details.value = s.details;
    details.style.setProperty('--p', s.details + '%');
    detailsVal.textContent = s.details === 0 ? 'Off' : s.details;
    $('#cfg-details-hint').textContent = hints[st.theme];
  }
  whenApi($('#cfg-frame'), function (api) {
    if (cfg === api) return;
    cfg = api;
    api.on('change', syncCfg);
    syncCfg();
  });
  radios(groups.theme, function (b) { if (cfg) cfg.setTheme(b.getAttribute('data-v')); });
  radios(groups.images, function (b) { if (cfg) cfg.update({ images: b.getAttribute('data-v') }); });
  radios(groups.lines, function (b) { if (cfg) cfg.update({ border: { style: b.getAttribute('data-v') } }); });
  radios(groups.radius, function (b) { var v = b.getAttribute('data-v'); if (cfg) cfg.update({ radius: v === 'keep' ? 'keep' : +v }); });
  radios(groups.typography, function (b) { if (cfg) cfg.update({ typography: b.getAttribute('data-v') }); });
  details.addEventListener('input', function () {
    details.style.setProperty('--p', details.value + '%');
    detailsVal.textContent = details.value === '0' ? 'Off' : details.value;
    if (cfg) cfg.update({ details: +details.value });
  });
  $('#cfg-reset').addEventListener('click', function () { if (cfg) cfg.resetTheme(); });
})();
